/* CSA5111 Question 32: independent executable */
#include "common/crypto_common.h"
static void q32(void){BIGNUM*p=BN_new(),*q=BN_new(),*g=BN_new(),*x=BN_new(),*y=BN_new(),*h=BN_new(),*k=BN_new(),*r=BN_new(),*s=BN_new(),*tmp=BN_new(),*kinv=NULL;BN_CTX*ctx=BN_CTX_new();BN_set_word(p,467);BN_set_word(q,233);BN_set_word(g,4);BN_set_word(x,127);BN_mod_exp(y,g,x,p,ctx);char msg[MAXBUF];readstr("Message to sign: ",msg,sizeof msg);unsigned char digest[32];unsigned int dn=0;EVP_Digest(msg,strlen(msg),digest,&dn,EVP_sha256(),NULL);BN_bin2bn(digest,(int)dn,h);BN_mod(h,h,q,ctx);puts("Toy DSA demonstration (p=467, q=233, g=4, private x=127). Do not use these toy parameters in production.");for(int sig=1;sig<=2;sig++){do{BN_rand_range(k,q);}while(BN_is_zero(k));BN_mod_exp(r,g,k,p,ctx);BN_mod(r,r,q,ctx);kinv=BN_mod_inverse(NULL,k,q,ctx);BN_mod_mul(tmp,x,r,q,ctx);BN_mod_add(tmp,tmp,h,q,ctx);BN_mod_mul(s,kinv,tmp,q,ctx);printf("Signature %d: r=",sig);BN_print_fp(stdout,r);printf(" s=");BN_print_fp(stdout,s);puts("");BN_free(kinv);kinv=NULL;}puts("Fresh random k values normally produce different signatures. Reusing k can expose the private key.");BN_free(p);BN_free(q);BN_free(g);BN_free(x);BN_free(y);BN_free(h);BN_free(k);BN_free(r);BN_free(s);BN_free(tmp);BN_CTX_free(ctx);}
int main(void){ OSSL_PROVIDER_load(NULL,"default"); OSSL_PROVIDER_load(NULL,"legacy"); q32(); return 0; }
